using InventoryWarehouseApi.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace InventoryWarehouseApi.Infrastructure.Persistence.Configurations;
internal sealed class LowStockThresholdConfiguration:IEntityTypeConfiguration<LowStockThreshold>{public void Configure(EntityTypeBuilder<LowStockThreshold>b){b.ToTable("LowStockThresholds",t=>{t.HasCheckConstraint("CK_LowStockThresholds_ThresholdQuantity_NonNegative","[ThresholdQuantity] >= 0");t.HasCheckConstraint("CK_LowStockThresholds_Timestamps","[UpdatedAtUtc] >= [CreatedAtUtc]");});b.HasKey(x=>x.Id);b.Property(x=>x.ThresholdQuantity).HasPrecision(18,3);b.HasOne<Product>().WithMany().HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Warehouse>().WithMany().HasForeignKey(x=>x.WarehouseId).OnDelete(DeleteBehavior.Restrict);b.HasOne<WarehouseLocation>().WithMany().HasForeignKey(x=>new{x.WarehouseId,x.WarehouseLocationId}).HasPrincipalKey(x=>new{x.WarehouseId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.ProductId,x.WarehouseId,x.WarehouseLocationId}).IsUnique().HasDatabaseName("UX_LowStockThresholds_Position");b.HasIndex(x=>new{x.IsEnabled,x.WarehouseId,x.ProductId});}}
